def make_plot(x, ay, by, a_mean, b_mean, a_points, b_points, a_name, b_name, title, xlabel, ax):
  ax.fill_between(x, ay, interpolate=True, alpha=0.25, facecolor='tab:blue', label=a_name)
  ax.plot(*zip(*a_points), marker='o', ls='', markersize=2, color='tab:blue')
  ax.axvline(a_mean, color='tab:blue')
  ax.fill_between(x, by, interpolate=True, alpha=0.25, facecolor='tab:orange', label=b_name)
  ax.plot(*zip(*b_points), marker='o', ls='', markersize=2, color='tab:orange')
  ax.axvline(b_mean, color='tab:orange')
  ax.tick_params(left=False, labelleft=False)
  ax.set_xlabel(xlabel)
  ax.set_ylabel('probability density, runs')
  ax.legend(loc='upper right')
  ax.set_title(title)
import matplotlib as mpl
mpl.use('svg')
import matplotlib.pyplot as plt
fig, axes = plt.subplots(2, 3)
if 2 == 1: axes = [axes]
row = col = 0
for i in range(6):
  make_plot(x[i], ay[i], by[i], a_means[i], b_means[i], a_points[i], b_points[i], r'quicksort', r'bubble', titles[i], xlabels[i], axes[row][col])
  col += 1
  if col >= 3:
    col = 0
    row += 1
while True:
  if row == 2: break
  axes[row][col].remove()
  col += 1
  if col >= 3:
    col = 0
    row += 1
figure = plt.gcf()
figure.set_size_inches(15, 10)
fig.tight_layout()
plt.savefig(r'.csbench/kde_cmp_all_groups_1_0.svg', dpi=100, bbox_inches='tight')
